// Lexique de la F1 (généré depuis le site web).

struct GlossaryEntry: Identifiable {
    let termFR: String, termEN: String, defFR: String, defEN: String
    var id: String { termFR }
    var term: String { isFrench ? termFR : termEN }
    var definition: String { isFrench ? defFR : defEN }
}

let glossary: [GlossaryEntry] = [
    GlossaryEntry(termFR: "Pole position", termEN: "Pole position", defFR: "Première place sur la grille de départ, obtenue par le plus rapide des qualifications.", defEN: "First place on the starting grid, earned by the fastest driver in qualifying."),
    GlossaryEntry(termFR: "Qualifications (Q1, Q2, Q3)", termEN: "Qualifying (Q1, Q2, Q3)", defFR: "Trois séances éliminatoires : les plus lents sont éliminés en Q1 puis en Q2, les 10 meilleurs se battent pour la pole en Q3.", defEN: "Three knockout sessions: the slowest drop out in Q1 and Q2, the top 10 fight for pole in Q3."),
    GlossaryEntry(termFR: "Sprint", termEN: "Sprint", defFR: "Course courte (~100 km) disputée le samedi de certains week-ends, avec ses propres qualifications et des points pour les 8 premiers.", defEN: "Short race (~100 km) held on Saturday at some events, with its own qualifying and points for the top 8."),
    GlossaryEntry(termFR: "Barème des points", termEN: "Points system", defFR: "Course : 25, 18, 15, 12, 10, 8, 6, 4, 2, 1 pour les 10 premiers. Sprint : 8 à 1 pour les 8 premiers. Le point du meilleur tour a été supprimé en 2025.", defEN: "Race: 25, 18, 15, 12, 10, 8, 6, 4, 2, 1 for the top 10. Sprint: 8 to 1 for the top 8. The fastest-lap point was dropped in 2025."),
    GlossaryEntry(termFR: "Tour de formation", termEN: "Formation lap", defFR: "Tour lent avant le départ pour chauffer pneus et freins, puis les voitures reprennent leur place sur la grille.", defEN: "Slow lap before the start to warm tyres and brakes, after which cars return to their grid slots."),
    GlossaryEntry(termFR: "Voiture de sécurité (SC)", termEN: "Safety Car (SC)", defFR: "Voiture qui neutralise la course après un incident : les pilotes roulent en file derrière elle sans dépasser, les écarts se resserrent.", defEN: "Car that neutralises the race after an incident: drivers queue up behind it without overtaking, gaps close up."),
    GlossaryEntry(termFR: "Voiture de sécurité virtuelle (VSC)", termEN: "Virtual Safety Car (VSC)", defFR: "Neutralisation sans voiture sur la piste : chaque pilote doit respecter un temps minimal, les écarts sont à peu près conservés.", defEN: "Neutralisation without a car on track: every driver must respect a minimum time, gaps are roughly kept."),
    GlossaryEntry(termFR: "Drapeau jaune", termEN: "Yellow flag", defFR: "Danger sur le côté de la piste : ralentir, interdiction de dépasser dans la zone. Double jaune : danger sur la piste, prêt à s'arrêter.", defEN: "Hazard beside the track: slow down, no overtaking in that zone. Double yellow: hazard on track, be ready to stop."),
    GlossaryEntry(termFR: "Drapeau rouge", termEN: "Red flag", defFR: "Course interrompue : toutes les voitures rentrent lentement dans la voie des stands.", defEN: "Session stopped: every car returns slowly to the pit lane."),
    GlossaryEntry(termFR: "Drapeau bleu", termEN: "Blue flag", defFR: "Montré à un pilote qui va être doublé : il doit laisser passer la voiture plus rapide.", defEN: "Shown to a driver about to be lapped: they must let the faster car through."),
    GlossaryEntry(termFR: "Drapeau à damier", termEN: "Chequered flag", defFR: "Fin de la séance ou de la course.", defEN: "End of the session or race."),
    GlossaryEntry(termFR: "Drapeau noir / noir et blanc", termEN: "Black / black-and-white flag", defFR: "Noir : pilote disqualifié. Noir et blanc : avertissement pour conduite antisportive.", defEN: "Black: driver disqualified. Black and white: warning for unsporting driving."),
    GlossaryEntry(termFR: "Arrêt aux stands", termEN: "Pit stop", defFR: "Passage au garage pendant la course pour changer les pneus (environ 2 s à l'arrêt, ~20 s perdues au total avec la voie des stands).", defEN: "Stop at the garage during the race to change tyres (about 2 s stationary, ~20 s lost overall including the pit lane)."),
    GlossaryEntry(termFR: "Undercut", termEN: "Undercut", defFR: "S'arrêter avant un rival pour profiter de pneus neufs plus rapides et ressortir devant lui après son propre arrêt.", defEN: "Pitting before a rival to use faster fresh tyres and come out ahead after they stop."),
    GlossaryEntry(termFR: "Overcut", termEN: "Overcut", defFR: "Rester en piste plus longtemps qu'un rival pour gagner du temps en air libre, puis ressortir devant après son arrêt.", defEN: "Staying out longer than a rival to gain time in clean air, then emerging ahead after stopping."),
    GlossaryEntry(termFR: "Gommes (tendre, medium, dur)", termEN: "Compounds (soft, medium, hard)", defFR: "Pneus secs : tendre (rouge) = rapide mais s'use vite, medium (jaune) = compromis, dur (blanc) = lent mais durable. Au moins deux gommes différentes en course sur le sec.", defEN: "Dry tyres: soft (red) = fast but wears quickly, medium (yellow) = balance, hard (white) = slower but durable. At least two different compounds in a dry race."),
    GlossaryEntry(termFR: "Intermédiaires et pluie", termEN: "Intermediates and wets", defFR: "Pneus verts pour piste humide, bleus pour forte pluie : ils évacuent l'eau pour éviter l'aquaplaning.", defEN: "Green tyres for a damp track, blue ones for heavy rain: they clear water to avoid aquaplaning."),
    GlossaryEntry(termFR: "Dégradation", termEN: "Degradation", defFR: "Perte de performance des pneus au fil des tours (usure, surchauffe) : elle dicte la stratégie d'arrêts.", defEN: "Loss of tyre performance over the laps (wear, overheating): it drives pit stop strategy."),
    GlossaryEntry(termFR: "Graining", termEN: "Graining", defFR: "Petits morceaux de gomme qui se détachent et se recollent sur le pneu, qui glisse davantage.", defEN: "Small pieces of rubber that tear off and stick back to the tyre, making it slide more."),
    GlossaryEntry(termFR: "Blistering", termEN: "Blistering", defFR: "Cloques dues à une surchauffe à l'intérieur du pneu.", defEN: "Blisters caused by overheating inside the tyre."),
    GlossaryEntry(termFR: "Secteurs", termEN: "Sectors", defFR: "Le tour est découpé en trois secteurs chronométrés. Violet : meilleur temps de tous, vert : record personnel, jaune : plus lent.", defEN: "The lap is split into three timed sectors. Purple: overall best, green: personal best, yellow: slower."),
    GlossaryEntry(termFR: "Écart (gap) et intervalle", termEN: "Gap and interval", defFR: "L'écart est la distance en secondes avec le leader, l'intervalle avec la voiture juste devant.", defEN: "The gap is the distance in seconds to the leader, the interval to the car just ahead."),
    GlossaryEntry(termFR: "Doublé (lapped)", termEN: "Lapped", defFR: "Pilote rattrapé et dépassé par le leader : il a un tour (ou plus) de retard.", defEN: "Driver caught and passed by the leader: one lap (or more) down."),
    GlossaryEntry(termFR: "DRS (jusqu'en 2025)", termEN: "DRS (until 2025)", defFR: "Aileron arrière ouvrant, autorisé à moins d'une seconde de la voiture de devant dans certaines zones, pour faciliter les dépassements. Remplacé en 2026 par l'aérodynamique active et le mode dépassement.", defEN: "Opening rear wing, allowed within one second of the car ahead in set zones to help overtaking. Replaced in 2026 by active aero and overtake mode."),
    GlossaryEntry(termFR: "Aérodynamique active (2026)", termEN: "Active aerodynamics (2026)", defFR: "Depuis 2026, les ailerons avant et arrière changent de position : faible traînée en ligne droite, appui maximal en courbe.", defEN: "Since 2026, front and rear wings change position: low drag on straights, maximum downforce in corners."),
    GlossaryEntry(termFR: "Mode dépassement (2026)", termEN: "Overtake mode (2026)", defFR: "Surplus d'énergie électrique qu'un pilote proche de la voiture de devant peut utiliser pour tenter un dépassement.", defEN: "Extra electrical energy a driver close to the car ahead can use to attempt an overtake."),
    GlossaryEntry(termFR: "Unité de puissance", termEN: "Power unit", defFR: "Moteur V6 turbo hybride. Depuis 2026 : environ moitié thermique, moitié électrique, avec carburant 100 % durable.", defEN: "Hybrid turbo V6 engine. Since 2026: roughly half combustion, half electric, running on 100% sustainable fuel."),
    GlossaryEntry(termFR: "ERS / MGU-K", termEN: "ERS / MGU-K", defFR: "Système de récupération d'énergie : le MGU-K récupère l'énergie au freinage et la restitue en accélération.", defEN: "Energy recovery system: the MGU-K harvests energy under braking and releases it under acceleration."),
    GlossaryEntry(termFR: "Effet de sol", termEN: "Ground effect", defFR: "Appui aérodynamique créé sous la voiture par le fond plat et ses tunnels, qui la plaque au sol.", defEN: "Downforce generated under the car by the floor and its tunnels, sucking it to the ground."),
    GlossaryEntry(termFR: "Appui aérodynamique", termEN: "Downforce", defFR: "Force qui plaque la voiture au sol pour aller plus vite en courbe, au prix de plus de traînée en ligne droite.", defEN: "Force pressing the car down to go faster through corners, at the cost of more drag on straights."),
    GlossaryEntry(termFR: "Parc fermé", termEN: "Parc fermé", defFR: "Après les qualifications, les réglages de la voiture sont gelés jusqu'à la course (sauf exceptions encadrées).", defEN: "After qualifying, car setups are frozen until the race (with limited exceptions)."),
    GlossaryEntry(termFR: "Pénalités", termEN: "Penalties", defFR: "5 ou 10 secondes ajoutées au temps (ou purgées au stand), drive-through (traverser la voie des stands), stop-and-go (s'arrêter 10 s), recul sur la grille.", defEN: "5 or 10 seconds added (or served at a stop), drive-through (pass through the pit lane), stop-and-go (stop for 10 s), grid drop."),
    GlossaryEntry(termFR: "Limites de piste", termEN: "Track limits", defFR: "Les quatre roues ne doivent pas franchir entièrement les lignes blanches : sinon tour annulé, puis pénalité en cas de récidive.", defEN: "All four wheels may not fully cross the white lines: otherwise the lap is deleted, then a penalty for repeat offences."),
    GlossaryEntry(termFR: "Pilote de réserve", termEN: "Reserve driver", defFR: "Pilote prêt à remplacer un titulaire malade ou blessé.", defEN: "Driver ready to replace an ill or injured race driver."),
    GlossaryEntry(termFR: "Plafond budgétaire", termEN: "Cost cap", defFR: "Limite de dépenses annuelle imposée aux écuries pour réduire les écarts entre équipes riches et modestes.", defEN: "Annual spending limit imposed on teams to narrow the gap between rich and smaller outfits."),
    GlossaryEntry(termFR: "Championnat constructeurs", termEN: "Constructors' championship", defFR: "Classement des écuries : addition des points de leurs deux pilotes. Il existe depuis 1958.", defEN: "Team standings: the sum of both drivers' points. It has existed since 1958."),
]
